public ConnectionQueryServicesImpl(QueryServices services, ConnectionInfo connectionInfo,
    Properties info) {
    super(services);
    Configuration config = HBaseFactoryProvider.getConfigurationFactory().getConfiguration();
    for (Entry<String, String> entry : services.getProps()) {
      config.set(entry.getKey(), entry.getValue());
    }
    if (info != null) {
      for (Object key : info.keySet()) {
        config.set((String) key, info.getProperty((String) key));
      }
    }
    for (Entry<String, String> entry : connectionInfo.asProps()) {
      config.set(entry.getKey(), entry.getValue());
    }
    if (connectionInfo.getPrincipal() != null) {
      config.set(QUERY_SERVICES_NAME, connectionInfo.getPrincipal());
    }
    LOGGER.info(String.format("CQS initialized with connection query service : %s",
      config.get(QUERY_SERVICES_NAME)));
    this.connectionInfo = connectionInfo;

    // Without making a copy of the configuration we cons up, we lose some of our properties
    // on the server side during testing. This allows the application overridden
    // ConfigurationFactory to inject/modify configs
    Configuration finalConfig =
      HBaseFactoryProvider.getConfigurationFactory().getConfiguration(config);
    this.config = finalConfig;

    if (finalConfig.getBoolean(CQSI_THREAD_POOL_ENABLED, DEFAULT_CQSI_THREAD_POOL_ENABLED)) {
      final int keepAlive = finalConfig.getInt(CQSI_THREAD_POOL_KEEP_ALIVE_SECONDS,
        DEFAULT_CQSI_THREAD_POOL_KEEP_ALIVE_SECONDS);
      final int corePoolSize = finalConfig.getInt(CQSI_THREAD_POOL_CORE_POOL_SIZE,
        DEFAULT_CQSI_THREAD_POOL_CORE_POOL_SIZE);
      final int maxThreads =
        finalConfig.getInt(CQSI_THREAD_POOL_MAX_THREADS, DEFAULT_CQSI_THREAD_POOL_MAX_THREADS);
      final int maxQueue =
        finalConfig.getInt(CQSI_THREAD_POOL_MAX_QUEUE, DEFAULT_CQSI_THREAD_POOL_MAX_QUEUE);
      final String threadPoolName = connectionInfo.getPrincipal() != null
        ? connectionInfo.getPrincipal()
        : DEFAULT_QUERY_SERVICES_NAME;
      // Based on implementations used in
      // org.apache.hadoop.hbase.client.ConnectionImplementation
      final BlockingQueue<Runnable> workQueue = new LinkedBlockingQueue<>(maxQueue);
      Supplier<HTableThreadPoolHistograms> hTableThreadPoolHistogramsSupplier =
        getThreadPoolHistogramsSupplier(maxThreads, maxQueue);
      this.threadPoolExecutor = new HTableThreadPoolWithUtilizationStats(corePoolSize, maxThreads,
        keepAlive, TimeUnit.SECONDS, workQueue,
        new ThreadFactoryBuilder().setDaemon(true)
          .setNameFormat(
            "CQSI-" + threadPoolName + "-" + threadPoolNumber.incrementAndGet() + "-shared-pool-%d")
          .setUncaughtExceptionHandler(Threads.LOGGING_EXCEPTION_HANDLER).build(),
        connectionInfo.toUrl(), hTableThreadPoolHistogramsSupplier);
      this.threadPoolExecutor
        .allowCoreThreadTimeOut(finalConfig.getBoolean(CQSI_THREAD_POOL_ALLOW_CORE_THREAD_TIMEOUT,
          DEFAULT_CQSI_THREAD_POOL_ALLOW_CORE_THREAD_TIMEOUT));
      LOGGER.info(
        "For ConnectionQueryService = {} , "
          + "CQSI ThreadPool Configs {} = {}, {} = {}, {} = {}, {} = {}, {} = {}",
        threadPoolName, CQSI_THREAD_POOL_KEEP_ALIVE_SECONDS,
        finalConfig.get(CQSI_THREAD_POOL_KEEP_ALIVE_SECONDS), CQSI_THREAD_POOL_CORE_POOL_SIZE,
        finalConfig.get(CQSI_THREAD_POOL_CORE_POOL_SIZE), CQSI_THREAD_POOL_MAX_THREADS,
        finalConfig.get(CQSI_THREAD_POOL_MAX_THREADS), CQSI_THREAD_POOL_MAX_QUEUE,
        finalConfig.get(CQSI_THREAD_POOL_MAX_QUEUE), CQSI_THREAD_POOL_ALLOW_CORE_THREAD_TIMEOUT,
        finalConfig.get(CQSI_THREAD_POOL_ALLOW_CORE_THREAD_TIMEOUT));
    }

    LOGGER.info(
      "CQS Configs {} = {} , {} = {} , {} = {} , {} = {} , {} = {} , {} = {} , {} = {}, {} = {}",
      HConstants.ZOOKEEPER_QUORUM, finalConfig.get(HConstants.ZOOKEEPER_QUORUM),
      HConstants.CLIENT_ZOOKEEPER_QUORUM, finalConfig.get(HConstants.CLIENT_ZOOKEEPER_QUORUM),
      HConstants.CLIENT_ZOOKEEPER_CLIENT_PORT,
      finalConfig.get(HConstants.CLIENT_ZOOKEEPER_CLIENT_PORT), HConstants.ZOOKEEPER_CLIENT_PORT,
      finalConfig.get(HConstants.ZOOKEEPER_CLIENT_PORT), RPCConnectionInfo.BOOTSTRAP_NODES,
      finalConfig.get(RPCConnectionInfo.BOOTSTRAP_NODES), HConstants.MASTER_ADDRS_KEY,
      finalConfig.get(HConstants.MASTER_ADDRS_KEY),
      ConnectionInfo.CLIENT_CONNECTION_REGISTRY_IMPL_CONF_KEY,
      finalConfig.get(ConnectionInfo.CLIENT_CONNECTION_REGISTRY_IMPL_CONF_KEY),
      QueryServices.CQSI_THREAD_POOL_ENABLED,
      finalConfig.get(QueryServices.CQSI_THREAD_POOL_ENABLED));

    // Set the rpcControllerFactory if it is a server side connnection.
    boolean isServerSideConnection = config.getBoolean(QueryUtil.IS_SERVER_CONNECTION, false);
    if (isServerSideConnection) {
      this.serverSideRPCControllerFactory = new ServerSideRPCControllerFactory(config);
    }
    // set replication required parameter
    ConfigUtil.setReplicationConfigIfAbsent(finalConfig);
    this.props = new ReadOnlyProps(finalConfig.iterator());
    this.userName = connectionInfo.getPrincipal();
    this.user = connectionInfo.getUser();
    this.latestMetaData = newEmptyMetaData();
    // TODO: should we track connection wide memory usage or just org-wide usage?
    // If connection-wide, create a MemoryManager here, otherwise just use the one from the delegate
    this.childServices = new ConcurrentHashMap<ImmutableBytesWritable, ConnectionQueryServices>(
      INITIAL_CHILD_SERVICES_CAPACITY);
    // find the HBase version and use that to determine the KeyValueBuilder that should be used
    String hbaseVersion = VersionInfo.getVersion();
    this.kvBuilder = KeyValueBuilder.get(hbaseVersion);
    this.returnSequenceValues = props.getBoolean(QueryServices.RETURN_SEQUENCE_VALUES_ATTRIB,
      QueryServicesOptions.DEFAULT_RETURN_SEQUENCE_VALUES);
    this.renewLeaseEnabled = config.getBoolean(RENEW_LEASE_ENABLED, DEFAULT_RENEW_LEASE_ENABLED);
    this.renewLeasePoolSize =
      config.getInt(RENEW_LEASE_THREAD_POOL_SIZE, DEFAULT_RENEW_LEASE_THREAD_POOL_SIZE);
    this.renewLeaseThreshold =
      config.getInt(RENEW_LEASE_THRESHOLD_MILLISECONDS, DEFAULT_RENEW_LEASE_THRESHOLD_MILLISECONDS);
    this.renewLeaseTaskFrequency = config.getInt(RUN_RENEW_LEASE_FREQUENCY_INTERVAL_MILLISECONDS,
      DEFAULT_RUN_RENEW_LEASE_FREQUENCY_INTERVAL_MILLISECONDS);
    List<LinkedBlockingQueue<WeakReference<PhoenixConnection>>> list =
      Lists.newArrayListWithCapacity(renewLeasePoolSize);
    for (int i = 0; i < renewLeasePoolSize; i++) {
      LinkedBlockingQueue<WeakReference<PhoenixConnection>> queue =
        new LinkedBlockingQueue<WeakReference<PhoenixConnection>>();
      list.add(queue);
    }
    connectionQueues = ImmutableList.copyOf(list);

    // A little bit of a smell to leak `this` here, but should not be a problem
    this.tableStatsCache =
      GUIDE_POSTS_CACHE_PROVIDER.getGuidePostsCache(props.get(GUIDE_POSTS_CACHE_FACTORY_CLASS,
        QueryServicesOptions.DEFAULT_GUIDE_POSTS_CACHE_FACTORY_CLASS), this, config);

    this.isAutoUpgradeEnabled =
      config.getBoolean(AUTO_UPGRADE_ENABLED, QueryServicesOptions.DEFAULT_AUTO_UPGRADE_ENABLED);
    this.maxConnectionsAllowed =
      config.getInt(QueryServices.CLIENT_CONNECTION_MAX_ALLOWED_CONNECTIONS,
        QueryServicesOptions.DEFAULT_CLIENT_CONNECTION_MAX_ALLOWED_CONNECTIONS);
    this.maxInternalConnectionsAllowed =
      config.getInt(QueryServices.INTERNAL_CONNECTION_MAX_ALLOWED_CONNECTIONS,
        QueryServicesOptions.DEFAULT_INTERNAL_CONNECTION_MAX_ALLOWED_CONNECTIONS);
    this.shouldThrottleNumConnections =
      (maxConnectionsAllowed > 0) || (maxInternalConnectionsAllowed > 0);
    this.enableConnectionActivityLogging = config.getBoolean(CONNECTION_ACTIVITY_LOGGING_ENABLED,
      QueryServicesOptions.DEFAULT_CONNECTION_ACTIVITY_LOGGING_ENABLED);
    this.loggingIntervalInMins = config.getInt(CONNECTION_ACTIVITY_LOGGING_INTERVAL,
      QueryServicesOptions.DEFAULT_CONNECTION_ACTIVITY_LOGGING_INTERVAL_IN_MINS);

    if (enableConnectionActivityLogging) {
      LoggingConnectionLimiter.Builder builder =
        new LoggingConnectionLimiter.Builder(shouldThrottleNumConnections);
      connectionLimiter = builder.withLoggingIntervalInMins(loggingIntervalInMins).withLogging(true)
        .withMaxAllowed(this.maxConnectionsAllowed)
        .withMaxInternalAllowed(this.maxInternalConnectionsAllowed).build();
    } else {
      DefaultConnectionLimiter.Builder builder =
        new DefaultConnectionLimiter.Builder(shouldThrottleNumConnections);
      connectionLimiter = builder.withMaxAllowed(this.maxConnectionsAllowed)
        .withMaxInternalAllowed(this.maxInternalConnectionsAllowed).build();
    }

    if (finalConfig.getBoolean(CLIENT_SIDE_METRICS_ENABLED_KEY, false)) {
      // "hbase.client.metrics.scope" defined on
      // org.apache.hadoop.hbase.client.MetricsConnection#METRICS_SCOPE_KEY
      // however we cannot use the constant directly as long as we support HBase 2.4 profile.
      finalConfig.set("hbase.client.metrics.scope", config.get(QUERY_SERVICES_NAME));
    }

    if (!QueryUtil.isServerConnection(props)) {
      // Start queryDistruptor everytime as log level can be change at connection level as well, but
      // we can avoid starting for server connections.
      try {
        this.queryDisruptor = new QueryLoggerDisruptor(finalConfig);
      } catch (SQLException e) {
        LOGGER.warn("Unable to initiate query logging service !!");
        e.printStackTrace();
      }
    }
    nSequenceSaltBuckets = config.getInt(QueryServices.SEQUENCE_SALT_BUCKETS_ATTRIB,
      QueryServicesOptions.DEFAULT_SEQUENCE_TABLE_SALT_BUCKETS);
    this.metricsMetadataCachingSource =
      MetricsPhoenixCoprocessorSourceFactory.getInstance().getMetadataCachingSource();
  }

